<?php
namespace App\Controllers;
use App\Core\Controller; use App\Core\Database; use App\Models\Reservation;
class ReservationController extends Controller { public function index(): void {$m=new Reservation();$this->render('reservations/index',['reservations'=>$m->all(),'clients'=>$m->clients(),'packages'=>$m->packages()]);} public function save(): void {\csrf_check();$m=new Reservation();$d=['code'=>'NET-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2))),'client_id'=>(int)($_POST['client_id']??0),'package_id'=>(int)($_POST['package_id']??0),'travel_date'=>$_POST['travel_date']??'','passengers'=>max(1,(int)($_POST['passengers']??1)),'total_amount'=>max(0,(float)($_POST['total_amount']??0)),'status'=>$_POST['status']??'Pendiente','notes'=>trim($_POST['notes']??'')];if(!$d['client_id']||!$d['package_id']||!$d['travel_date']||$d['total_amount']<=0){\flash('error','Completa cliente, paquete, fecha y monto total.');\redirect('reservations');}try{$s=Database::connection()->prepare("SELECT stock,price FROM packages WHERE id=? AND status='Activo'");$s->execute([$d['package_id']]);$pkg=$s->fetch();if(!$pkg)throw new \RuntimeException();$m->save($d);\flash('success','Reserva registrada con código '.$d['code'].'.');}catch(\Throwable $e){\flash('error','No se pudo registrar la reserva. Verifica los datos.');}\redirect('reservations');} }
